"use client";

import React from "react";

export interface IconProps extends React.SVGProps<SVGSVGElement> {
  className?: string;
  strokeWidth?: number;
  fill?: string;
  filled?: boolean;
}

const IconBase: React.FC<IconProps> = ({
  children,
  className = "h-5 w-5",
  strokeWidth = 1.75,
  fill = "none",
  ...props
}) => (
  <svg
    viewBox="0 0 24 24"
    fill={fill}
    stroke="currentColor"
    strokeWidth={strokeWidth}
    strokeLinecap="round"
    strokeLinejoin="round"
    className={className}
    aria-hidden="true"
    {...props}
  >
    {children}
  </svg>
);

